import reimport globimport warningsfrom pathlib import Pathimport numpy as npimport pandas as pdfrom astropy.io import fitsfrom astropy.io.fits.verify import VerifyWarning# -----------------------------# Silence noisy FITS warnings# -----------------------------warnings.filterwarnings("ignore", message=".*header keyword is invalid.*")warnings.filterwarnings("ignore", module="astropy.io.fits.card")warnings.simplefilter("ignore", VerifyWarning)TARGETS_CSV = "ASTR502_Master_Target_List.csv"OUTCSV = "Carmen_master_spectra.csv"KOA_GLOB = "data/organized_spectra/**/*.*fits*"# ============================================================# Target lookup helpers# ============================================================def normalize_name(s: str) -> str:    s = str(s).lower().strip()    s = s.replace("’", "").replace("'", "")    s = re.sub(r"[\s\-_]+", "", s)    return sdef clean_obj_name(s: str) -> str:    s = str(s).strip()    s = s.replace("TOI ", "TOI-").replace("TIC ", "TIC")    s = re.sub(r"\s+", " ", s)    return sdef build_target_lookup(targets_df: pd.DataFrame) -> dict:    lookup = {}    cols = {c.lower(): c for c in targets_df.columns}    ra_col = cols.get("ra")    dec_col = cols.get("dec")    hostname_col = cols.get("hostname")    plname_col = cols.get("pl_name")    for _, row in targets_df.iterrows():        ra = float(row[ra_col]) if ra_col and pd.notna(row.get(ra_col, np.nan)) else np.nan        dec = float(row[dec_col]) if dec_col and pd.notna(row.get(dec_col, np.nan)) else np.nan        names = []        if hostname_col and pd.notna(row.get(hostname_col, np.nan)):            names.append(str(row[hostname_col]))        if plname_col and pd.notna(row.get(plname_col, np.nan)):            names.append(str(row[plname_col]))        for name in names:            key = normalize_name(name)            if key:                lookup[key] = (name, ra, dec)    return lookupdef infer_target_from_text(text: str, lookup: dict) -> tuple[str, float, float]:    tnorm = normalize_name(text)    best = None    best_len = -1    for key, (name, ra, dec) in lookup.items():        if key and key in tnorm and len(key) > best_len:            best = (name, ra, dec)            best_len = len(key)    if best is None:        return ("UNKNOWN", np.nan, np.nan)    return bestdef infer_target_from_path(fp: str, lookup: dict) -> tuple[str, float, float]:    p = Path(fp)    candidates = []    for k in [p.parent.name, p.parent.parent.name, p.parent.parent.parent.name]:        if k and k not in candidates:            candidates.append(k)    for cand in candidates:        host, ra, dec = infer_target_from_text(cand, lookup)        if host != "UNKNOWN":            return host, ra, dec    if candidates:        return candidates[0], np.nan, np.nan    return ("UNKNOWN", np.nan, np.nan)def keep_koa_file(fp: str) -> bool:    p = fp.lower()    bad = [        "arc", "arcids", "bias", "dark", "flat", "trace", "lamp", "thar", "calib",        "focus", "pin", "engineering"    ]    if any(b in p for b in bad):        return False    if "/anc/" in p or "/cal/" in p:        return False    return Truedef file_size_ok(fp: str) -> bool:    try:        return Path(fp).stat().st_size > 10_000    except Exception:        return Falsedef get_header_str(hdr, *keys, default="UNKNOWN"):    for k in keys:        try:            v = hdr.get(k, None)            if v is None:                continue            s = str(v).strip()            if s:                return s        except Exception:            pass    return default# ============================================================# Table column picking helper# ============================================================def pick_col_contains(names, keys):    names_u = [str(n).upper() for n in names]    for key in keys:        ku = key.upper()        for orig, up in zip(names, names_u):            if ku in up:                return orig    return None# ============================================================# Multispec (IRAF) wavelength handling# ============================================================def multispec_specs_from_header(hdr) -> dict[int, str]:    wat_keys = [k for k in hdr.keys() if str(k).upper().startswith("WAT2_")]    if not wat_keys:        return {}    wat_keys = sorted(wat_keys, key=lambda k: int(str(k).split("_")[1]))    chunks = [str(hdr[k]) for k in wat_keys]    specs: dict[int, str] = {}    collecting = False    current_idx = None    buf = []    start_pat = re.compile(r"spec\s*(\d+)\s*=\s*\"")    for chunk in chunks:        s = chunk.replace("\n", " ")        pos = 0        while pos < len(s):            if not collecting:                m = start_pat.search(s, pos)                if not m:                    break                current_idx = int(m.group(1))                collecting = True                buf = []                pos = m.end()            else:                q = s.find('"', pos)                if q == -1:                    buf.append(s[pos:])                    break                buf.append(s[pos:q])                specs[current_idx] = "".join(buf).strip()                collecting = False                current_idx = None                buf = []                pos = q + 1    return specsdef _wavelength_from_multispec_spec(spec_str: str):    nums = [float(x) for x in re.findall(r"[+-]?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?", spec_str)]    if len(nums) < 6:        return None    try:        dtype = int(round(nums[2]))  # 0 linear, 1 log10(lambda) common        w1 = float(nums[3])        dw = float(nums[4])        n = int(round(nums[5]))    except Exception:        return None    if n <= 10:        return None    pix = np.arange(n, dtype=float)    if dtype == 1:        wave = 10 ** (w1 + dw * pix)    else:        wave = w1 + dw * pix    if np.nanmean(np.diff(wave) > 0) < 0.5:        wave = wave[::-1]    if not np.isfinite(wave).all():        return None    return wavedef wave_flux_from_multispec_primary(primary_hdu):    data = np.asarray(primary_hdu.data)    hdr = primary_hdu.header    if data is None or data.ndim != 2:        return []    n_orders, _ = data.shape    specs = multispec_specs_from_header(hdr)    if not specs:        return []    orders = []    for order_idx in range(1, n_orders + 1):        spec_str = specs.get(order_idx, None)        if not spec_str:            continue        wave = _wavelength_from_multispec_spec(spec_str)        if wave is None:            continue        flux = np.array(data[order_idx - 1, :], dtype=float)        n = min(wave.size, flux.size)        if n > 50:            orders.append((wave[:n], flux[:n]))    return orders# ============================================================# Non-multispec wavelength/flux extraction# ============================================================def linear_wavelength_from_header(hdr, npts: int):    crval = hdr.get("CRVAL1", None)    cdelt = hdr.get("CDELT1", hdr.get("CD1_1", None))    crpix = hdr.get("CRPIX1", 1.0)    if crval is None or cdelt is None:        return None    try:        crval = float(crval)        cdelt = float(cdelt)        crpix = float(crpix)    except Exception:        return None    i = np.arange(npts, dtype=float)    lam = crval + (i + 1.0 - crpix) * cdelt    return lamdef find_wave_flux_from_primary_matrix(data2d: np.ndarray):    d = np.array(data2d, dtype=float)    if d.ndim != 2:        return None, None    n_tracks, _ = d.shape    if n_tracks < 2 or n_tracks > 30:        return None, None    wave_scores = []    for i in range(n_tracks):        v = d[i]        m = np.isfinite(v)        if m.sum() < 50:            wave_scores.append((-1, i))            continue        vv = v[m]        inc = np.mean(np.diff(vv) > 0)        vmin, vmax = float(np.nanmin(vv)), float(np.nanmax(vv))        plausible = (100 < vmin < 20000) and (100 < vmax < 20000) and (vmax > vmin)        score = inc if plausible else -1        wave_scores.append((score, i))    wave_scores.sort(reverse=True)    best_score, wave_i = wave_scores[0]    if best_score < 0.90:        return None, None    wave = d[wave_i]    flux_i = None    best_flux_score = -1    for i in range(n_tracks):        if i == wave_i:            continue        v = d[i]        m = np.isfinite(v)        if m.sum() < 50:            continue        vv = v[m]        inc = np.mean(np.diff(vv) > 0)        score = (1 - inc) * np.nanpercentile(np.abs(vv), 90)        if score > best_flux_score:            best_flux_score = score            flux_i = i    if flux_i is None:        return None, None    flux = d[flux_i]    n = min(wave.size, flux.size)    if n <= 50:        return None, None    return wave[:n], flux[:n]def find_flux_wave_in_hdul(hdul):    # 1) Tables with wave + flux    for hdu in hdul:        if isinstance(hdu, (fits.BinTableHDU, fits.TableHDU)) and getattr(hdu, "columns", None) is not None:            names = list(hdu.columns.names or [])            if not names:                continue            wcol = pick_col_contains(names, ["WAVE", "WAVEL", "LAMBDA", "LAM", "WL"])            fcol = pick_col_contains(names, ["FLUX", "SUM_FLUX", "SPEC", "SPECT", "COUNTS", "INTENS"])            if wcol and fcol:                wave = np.array(hdu.data[wcol], dtype=float).ravel()                flux = np.array(hdu.data[fcol], dtype=float).ravel()                n = min(wave.size, flux.size)                if n > 50:                    return wave[:n], flux[:n]    # 2) 2D track stacks (wave+flux)    for hdu in hdul:        data = getattr(hdu, "data", None)        if isinstance(data, np.ndarray) and data.ndim == 2 and 2 <= data.shape[0] <= 30:            wave, flux = find_wave_flux_from_primary_matrix(data)            if wave is not None and flux is not None:                return wave, flux    # 3) 1D image with linear WCS    for hdu in hdul:        data = getattr(hdu, "data", None)        hdr = getattr(hdu, "header", None)        if data is None or hdr is None:            continue        if isinstance(data, np.ndarray) and data.ndim == 1 and data.size > 50:            wave = linear_wavelength_from_header(hdr, data.size)            if wave is not None:                return wave, np.array(data, dtype=float)            # flux-only 1D (no wavelength)            return None, np.array(data, dtype=float)    # 4) Flux-only 2D images (orders x pixels) — THIS is what restores your ~1100 SNR_General    for hdu in hdul:        data = getattr(hdu, "data", None)        if isinstance(data, np.ndarray) and data.ndim == 2 and data.size > 200:            return None, np.array(data, dtype=float)    return None, None# ============================================================# SNR helpers# ============================================================def robust_snr(flux: np.ndarray) -> float:    f = np.array(flux, dtype=float).ravel()    f = f[np.isfinite(f)]    if f.size < 50:        return np.nan    signal = np.nanmedian(np.abs(f))    if not np.isfinite(signal) or signal == 0:        return np.nan    df = np.diff(f)    if df.size < 20:        return np.nan    mad = np.median(np.abs(df - np.median(df)))    sigma = 1.4826 * mad / np.sqrt(2.0)    if not np.isfinite(sigma) or sigma <= 0:        return np.nan    return float(signal / sigma)def snr_in_window(wave, flux, wmin, wmax):    if wave is None:        return np.nan    w = np.array(wave, dtype=float).ravel()    f = np.array(flux, dtype=float).ravel()    m = np.isfinite(w) & np.isfinite(f) & (w >= wmin) & (w <= wmax)    if m.sum() < 30:        return np.nan    return robust_snr(f[m])def compute_snrs_and_range_from_fits(fp: str):    """    Returns:      snr_gen, snr_li, snr_ha, snr_ca, wlow, whigh    """    with fits.open(fp, memmap=False) as hdul:        h0 = hdul[0]        hdr0 = h0.header        is_multispec = ("WAT0_001" in hdr0) or any(str(k).upper().startswith("WAT2_") for k in hdr0.keys())        # Multispec orders in primary        if is_multispec and isinstance(h0.data, np.ndarray) and h0.data.ndim == 2:            orders = wave_flux_from_multispec_primary(h0)            if orders:                wmins = []                wmaxs = []                order_snrs = []                for w, f in orders:                    wmins.append(float(np.nanmin(w)))                    wmaxs.append(float(np.nanmax(w)))                    s = robust_snr(f)                    if np.isfinite(s):                        order_snrs.append(s)                wlow = float(np.nanmin(wmins)) if wmins else np.nan                whigh = float(np.nanmax(wmaxs)) if wmaxs else np.nan                if order_snrs:                    order_snrs = np.sort(np.array(order_snrs))                    snr_gen = float(np.median(order_snrs[len(order_snrs) // 2 :]))                else:                    snr_gen = np.nan                def best_snr_in_window(wmin, wmax):                    vals = []                    for w, f in orders:                        s = snr_in_window(w, f, wmin, wmax)                        if np.isfinite(s):                            vals.append(s)                    return float(np.nanmax(vals)) if vals else np.nan                snr_li = best_snr_in_window(6707.0, 6711.0)                snr_ha = best_snr_in_window(6560.0, 6566.0)                snr_ca = best_snr_in_window(3929.0, 3972.0)                return snr_gen, snr_li, snr_ha, snr_ca, wlow, whigh        # Fallback: tables/WCS/flux-only        wave, flux = find_flux_wave_in_hdul(hdul)        wlow = np.nan        whigh = np.nan        if wave is not None:            ww = np.array(wave, dtype=float).ravel()            ww = ww[np.isfinite(ww)]            if ww.size > 10:                wlow = float(np.nanmin(ww))                whigh = float(np.nanmax(ww))        if flux is None:            return np.nan, np.nan, np.nan, np.nan, wlow, whigh        # Flux-only 2D: compute SNR_General per-order and keep line SNRs NaN        if isinstance(flux, np.ndarray) and flux.ndim == 2:            order_snrs = []            for i in range(flux.shape[0]):                s = robust_snr(flux[i, :])                if np.isfinite(s):                    order_snrs.append(s)            if order_snrs:                order_snrs = np.sort(np.array(order_snrs))                snr_gen = float(np.median(order_snrs[len(order_snrs) // 2 :]))            else:                snr_gen = np.nan            return snr_gen, np.nan, np.nan, np.nan, wlow, whigh        # Normal 1D case (with or without wave)        snr_gen = robust_snr(flux)        snr_li = snr_in_window(wave, flux, 6707.0, 6711.0)        snr_ha = snr_in_window(wave, flux, 6560.0, 6566.0)        snr_ca = snr_in_window(wave, flux, 3929.0, 3972.0)        return snr_gen, snr_li, snr_ha, snr_ca, wlow, whigh# ============================================================# main# ============================================================def main():    targets = pd.read_csv(TARGETS_CSV)    lookup = build_target_lookup(targets)    files = sorted(set(glob.glob(KOA_GLOB, recursive=True)))    files = [f for f in files if keep_koa_file(f)]    files = [f for f in files if file_size_ok(f)]    print("Found organized spectra files (filtered):", len(files))    rows = []    for fp in files:        try:            with fits.open(fp, memmap=False) as hdul:                hdr0 = hdul[0].header                instrument = get_header_str(hdr0, "INSTRUME", "TELESCOP", default="UNKNOWN")                obj = get_header_str(hdr0, "OBJECT", "TARGNAME", "TARGET", default="UNKNOWN")            snr_gen, snr_li, snr_ha, snr_ca, wlow, whigh = compute_snrs_and_range_from_fits(fp)            host, ra, dec = infer_target_from_text(clean_obj_name(obj), lookup)            if host == "UNKNOWN":                host, ra, dec = infer_target_from_text(fp, lookup)            if host == "UNKNOWN":                host, ra, dec = infer_target_from_path(fp, lookup)            rows.append(                {                    "Filename": fp,                    "Target": host,                    "RA": ra,                    "Dec": dec,                    "instrument": instrument,                    "SNR_General": snr_gen,                    "SNR-Li": snr_li,                    "SNR_Ha": snr_ha,                    "SNR_Ca": snr_ca,                    "wavelength-low": wlow,                    "wavelength-high": whigh,                }            )        except Exception:            rows.append(                {                    "Filename": fp,                    "Target": "UNKNOWN",                    "RA": np.nan,                    "Dec": np.nan,                    "instrument": "UNKNOWN",                    "SNR_General": np.nan,                    "SNR-Li": np.nan,                    "SNR_Ha": np.nan,                    "SNR_Ca": np.nan,                    "wavelength-low": np.nan,                    "wavelength-high": np.nan,                }            )    df = pd.DataFrame(rows)    # EXACT column order your prof wants    df = df[        [            "Filename",            "Target",            "RA",            "Dec",            "instrument",            "SNR_General",            "SNR-Li",            "SNR_Ha",            "SNR_Ca",            "wavelength-low",            "wavelength-high",        ]    ]    df.to_csv(OUTCSV, index=False)    print(f"Wrote {OUTCSV} with {len(df)} rows")    n_with_snr = int(df["SNR_General"].notna().sum())    print(f"SNR present in {n_with_snr}/{len(df)} rows")if __name__ == "__main__":    main()